mkdir -p migrations/down && cat > migrations/002_login_attempts.sql <<'EOF'
-- Rate limiting for POST /login; shared by all servers.
create table login_attempts (
  key text primary key,
  n integer not null check (n >= 0),
  since timestamptz not null default now()
);
EOF
cat > migrations/down/002_login_attempts.sql <<'EOF'
drop table login_attempts;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { pool } from "./db.ts";\nimport { hashPassword, verifyPassword } from "./passwords.ts";\n\nconst WINDOW = "15 minutes";\nconst MAX_PER_EMAIL = 10;\nconst MAX_PER_IP = 50;\n\n// Count the try first, atomically, in the database. The window restarts once it has expired.\nasync function countAttempt(key: string): Promise<number> {\n  const { rows } = await pool.query(\n    `insert into login_attempts (key, n, since) values ($1, 1, now())\n     on conflict (key) do update set\n       n = case when login_attempts.since < now() - interval \'${WINDOW}\' then 1 else login_attempts.n + 1 end,\n       since = case when login_attempts.since < now() - interval \'${WINDOW}\' then now() else login_attempts.since end\n     returning n`,\n    [key],\n  );\n  return rows[0].n;\n}\n\n// Used to spend the same time on unknown accounts as on wrong passwords.\nconst dummyHash = await hashPassword("dummy-password");',1)
s=s.replace('''  app.use(auth);
''','''  app.post("/login", async (req, res) => {
    const { email, password } = req.body ?? {};
    if (typeof email !== "string" || typeof password !== "string" || !email || !password || email.length > 320 || password.length > 1024) {
      return sendError(res, 400, "invalid_request", "email and password are required strings");
    }
    const normalized = email.trim().toLowerCase();
    const [perEmail, perIp] = await Promise.all([
      countAttempt(`login:email:${normalized}`),
      countAttempt(`login:ip:${req.ip ?? "unknown"}`),
    ]);
    if (perEmail > MAX_PER_EMAIL || perIp > MAX_PER_IP) {
      return sendError(res, 429, "too_many_attempts", "Try again later");
    }
    const { rows } = await pool.query("select api_token, password_hash from users where lower(email) = $1", [normalized]);
    const ok = await verifyPassword(password, rows[0]?.password_hash ?? dummyHash);
    if (rows.length === 0 || !ok) return sendError(res, 401, "invalid_credentials", "Invalid email or password");
    res.json({ token: rows[0].api_token });
  });

  app.use(auth);
''',1)
open(p,'w').write(s)

